"""Pydantic schemas and JSON output contracts for Local LLM Evidence Analysis."""

from typing import Any, Dict, List, Literal, Optional
from pydantic import BaseModel, Field, field_validator


class LLMEvidenceAnalysisResponse(BaseModel):
    """Structured, verifiable audit evaluation generated by local LLM (qwen3:4b)."""

    verdict: Literal[
        "compliant",
        "partially_compliant",
        "gap_detected",
        "not_addressed",
        "insufficient_evidence",
    ] = Field(..., description="Audit verdict regarding evidence conformity to requirement")
    
    confidence: float = Field(
        ..., ge=0.0, le=1.0, description="Model confidence score in the evaluation (0.0 to 1.0)"
    )
    
    explanation: str = Field(
        ..., min_length=15, description="Clear, professional audit explanation of how evidence satisfies or misses requirement"
    )
    
    cited_evidence_excerpt: Optional[str] = Field(
        None, description="Exact verbatim phrase or quote from the evidence supporting the conclusion"
    )
    
    cited_document_number: Optional[str] = Field(
        None, description="Exact controlled document number cited from provided metadata"
    )
    
    cited_revision: Optional[str] = Field(
        None, description="Exact revision identifier cited from provided metadata"
    )
    
    cited_section: Optional[str] = Field(
        None, description="Exact section number or title cited from provided metadata"
    )
    
    cited_pages: Optional[str] = Field(
        None, description="Exact page or page range cited from provided metadata"
    )
    
    missing_evidence: List[str] = Field(
        default_factory=list,
        description="Specific mandatory elements or controls absent from the provided evidence",
    )
    
    inconsistencies: List[str] = Field(
        default_factory=list,
        description="Contradictions, discrepancies, or ambiguities identified in the evidence",
    )
    
    unsupported_conclusions_detected: bool = Field(
        False, description="Flag indicating whether evidence text fails to support the required compliance claims"
    )
    
    recommended_remediation: Optional[str] = Field(
        None, description="Actionable recommendation to address identified gaps"
    )

    @field_validator("confidence", mode="before")
    @classmethod
    def parse_confidence(cls, v: Any) -> float:
        if isinstance(v, (int, float)):
            return max(0.0, min(1.0, float(v)))
        try:
            return max(0.0, min(1.0, float(str(v).strip().rstrip("%")) / 100.0 if "%" in str(v) else float(v)))
        except Exception:
            return 0.5


class LLMAnalysisRequest(BaseModel):
    clause_number: str = Field(..., description="ISO 13485 clause number, e.g. '7.5.6'")
    clause_title: str = Field(..., description="Title of the ISO clause")
    clause_text: str = Field(..., description="Normative or full text of the ISO clause")
    summary_requirements: str = Field(..., description="Key requirement summary bullets")
    document_number: Optional[str] = Field(None, description="Controlled document number")
    document_revision: Optional[str] = Field(None, description="Controlled document revision")
    section_title: Optional[str] = Field(None, description="Section title where evidence was found")
    section_number: Optional[str] = Field(None, description="Section number where evidence was found")
    page_start: Optional[int] = Field(None, description="Starting page of evidence")
    page_end: Optional[int] = Field(None, description="Ending page of evidence")
    evidence_text: Optional[str] = Field(None, description="Evidence excerpt text from document")
    model_name: Optional[str] = Field("qwen3:4b", description="Model to use ('qwen3:4b' or 'qwen3:8b')")
